\textnormal{(See, e.g.,~[Dembo-Zeitouni:Large_deviations_techniques_and_applications].)}

Fix $T \in (0,\infty)$. 
The family of laws of $(\sqrt{\kappa}B|_{[0,T]})_{\kappa > 0}$ 
satisfy an LDP on $(C^{0}_{}[0,T],|\!|\cdot|\!|_\infty)$ with good rate function 
\begin{align}
I_{T}(W) := \; & \begin{cases}
\frac{1}{2}\int_0^T (\frac{\,\mathrm{d}}{\,\mathrm{d} t} W_t)^2 \,\mathrm{d} t, & W \textnormal{ absolutely continuous},\\
+ \infty , & \textnormal{otherwise}.
\end{cases}
\end{align}

The family $(\smash{\accentset{\leftarrow}{\mathbf P}^{\kappa}})_{\kappa > 0}$ of laws of the $\operatorname{SLE}_{\kappa}$ curves viewed as probability measures on $(\smash{\accentset{\leftarrow}{\mathfrak{X}_{}}}, \smash{\accentset{\leftarrow}{\mathcal}{T}_{d_{\mathfrak{X}_{}}}})$ satisfy an LDP with good rate function $\smash{\accentset{\leftarrow}{I_{}}} \colon \smash{\accentset{\leftarrow}{X}} \to [0,+\infty]$, 
\begin{align*}
\smash{\accentset{\leftarrow}{I_{}}}(\smash{\accentset{\leftarrow}{\iota}}(\gamma)) := \sup_{t > 0}I_{t}(\gamma[0,t]) , \qquad \smash{\accentset{\leftarrow}{\iota}}(\gamma) = \big( \gamma[0,t] \big)_{t > 0} \in \smash{\accentset{\leftarrow}{\mathfrak{X}_{}}} .
\end{align*}
